[DataContractAttribute]
class HSMobileOpsItemRequest
{
    DataAreaId dataAreaId;
    str itemId;

}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('ItemId')]
public str parmItemId(str _value = itemId)
{
    itemId = _value;
    return itemId;
}
